// src/hook/useCustomLogin.jsx
import { Navigate, useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { loginPostAsync, logout } from "../slice/loginSlice";
import { IS_DEMO } from "../api/demoConfig";

const useCustomLogin = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();

  // isLogin은 불린으로 가정
  const { isLogin, user } = useSelector(state => state.login) || { isLogin: false, user: null };
  const isLoggedIn = !!isLogin;

  const doLogin = async (loginParam) => {
    const action = await dispatch(loginPostAsync(loginParam));
    return action.payload;
  };

  const doLogout = () => dispatch(logout());

  const moveToPath = (path) => navigate(path, { replace: true });
  const moveToLogin = () => navigate("/login", { replace: true });

  const moveToLoginReturn = () => <Navigate replace to="/login" />;

  // 데모일 때는 무조건 앱을 보여주고 싶다면 여기에 한 줄 더:
  if (IS_DEMO && !isLoggedIn) {
    // 데모 모드에서는 로그인 체크 X
    // 단순히 isLoggedIn을 true로 쓰거나 상위 ProtectedRouter에서 우회 처리
  }

  return { loginState: isLogin, isLoggedIn, user, doLogin, doLogout, moveToPath, moveToLogin, moveToLoginReturn };
};

export default useCustomLogin;
